<?php $page_title='Customers';require 'includes/header.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)$_POST['id'];$a=$_POST['action'];if($a==='delete'){$pdo->prepare("DELETE FROM users WHERE id=? AND role='customer'")->execute([$id]);flash('success','Customer deleted.');}if($a==='status'){$pdo->prepare("UPDATE users SET status=? WHERE id=? AND role='customer'")->execute([$_POST['status'],$id]);flash('success','Customer status updated.');}header('Location: customers.php');exit;}$q=trim($_GET['q']??'');$s=$pdo->prepare("SELECT u.*,COUNT(o.id) order_count,COALESCE(SUM(CASE WHEN o.order_status<>'cancelled' THEN o.total ELSE 0 END),0) spending FROM users u LEFT JOIN orders o ON o.user_id=u.id WHERE u.role='customer' AND (u.name LIKE ? OR u.email LIKE ? OR u.phone LIKE ?) GROUP BY u.id ORDER BY u.created_at DESC");$s->execute(["%$q%","%$q%","%$q%"]);$customers=$s->fetchAll();?>
<div class="page-head"><div><h1>Customers</h1><p>Accounts, spending and order history.</p></div></div><div class="panel"><form class="filters"><input class="input" name="q" value="<?=e($q)?>" placeholder="Search name, email or phone"><button class="btn">Search</button></form><div class="table-wrap"><table><tr><th>Customer</th><th>Phone</th><th>Registered</th><th>Orders</th><th>Total spending</th><th>Status</th><th>Actions</th></tr><?php foreach($customers as $c):?><tr><td><strong><?=e($c['name'])?></strong><br><?=e($c['email'])?></td><td><?=e($c['phone']??'—')?></td><td><?=date('M d, Y',strtotime($c['created_at']))?></td><td><?=$c['order_count']?></td><td><?=money((float)$c['spending'])?></td><td><?=e($c['status'])?></td><td><a class="btn light" href="customer-details.php?id=<?=$c['id']?>">View</a> <form style="display:inline" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?=$c['id']?>"><input type="hidden" name="status" value="<?=$c['status']==='active'?'blocked':'active'?>"><button class="btn light"><?=$c['status']==='active'?'Block':'Activate'?></button></form> <form style="display:inline" method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="btn danger" data-confirm="Delete this customer account? Their order history will remain.">Delete</button></form></td></tr><?php endforeach;?></table></div></div><?php require 'includes/footer.php';?>
